/* V108: التنقل بين أيام المسواك */
let buyView='';
function bdNorm(x){ const n=String(x||'').match(/\d+/g)||[]; if(n.length<3) return null; const y=n.find(v=>v.length===4)||n[0], r=n.filter(v=>v!==y); const iso=/^\D*\d{4}/.test(String(x)); return new Date(+y,(iso?+r[0]:+r[1])-1,iso?+r[1]:+r[0]) }
function bdLabel(x){ const d=bdNorm(x); return d?d.toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'short',day:'numeric',month:'numeric'}):esc(String(x)) }
function buyDays(){
  const d=settings.daily, strip=document.getElementById('bdStrip'); if(!strip) return;
  const days=[''].concat((d.history||[]).map(h=>h.date));
  if(buyView&&!days.includes(buyView)) buyView='';
  strip.innerHTML=days.map(x=>{ const h=x?d.history.find(z=>z.date===x):null;
    return `<button type="button" data-d="${esc(x)}" class="${x===buyView?'on':''}"><b>${x?bdLabel(x):'اليوم'}</b><small>${fmt(x?(h.total||0):buyTotals(d.items).t)}</small></button>` }).join('');
  const i=days.indexOf(buyView);
  document.getElementById('bdPrev').disabled=i>=days.length-1;
  document.getElementById('bdNext').disabled=i<=0;
  const on=strip.querySelector('.on'); if(on&&on.scrollIntoView&&document.getElementById('page-buy').classList.contains('active')) on.scrollIntoView({block:'nearest',inline:'nearest'});
  document.getElementById('buyHist').hidden=true;
  if(!buyView){ document.getElementById('buyTitle').textContent='مسواك اليوم'; return }
  const h=d.history.find(z=>z.date===buyView);
  document.getElementById('buyTitle').textContent='مسواك '+bdLabel(buyView);
  document.getElementById('buyDate').textContent='';
  document.getElementById('buySum').innerHTML=Object.entries(h.by||{}).map(([b,v])=>`<div class="bs"><span>${esc(b)}</span><b>${fmt(v)} د.ع</b></div>`).join('')+`<div class="bs all"><span>المجموع</span><b>${fmt(h.total||0)} د.ع</b></div>`;
  document.getElementById('buyList').innerHTML=(h.items&&h.items.length)?h.items.slice().reverse().map(e=>{ const df=buyItemDef(e.kind||'free'); const tm=e.ts?new Date(e.ts).toLocaleTimeString('ar-IQ-u-nu-latn',{hour:'numeric',minute:'2-digit'}):'';
    return `<div class="brow"><span class="bwho">${esc(e.buyer||'')}</span><div class="bwhat"><b>${esc(e.name)}</b><small>${[df?(fmt(e.qty)+' '+df.unit+(e.size?' × '+fmt(e.size)+' '+(buySize(e.kind).u):'')):(e.qty>1?'×'+fmt(e.qty):''),tm].filter(Boolean).join('، ')}</small></div><span class="bcost">${fmt(e.cost)} د.ع</span></div>` }).join('')
    :'<div class="empty-cart">تفاصيل هذا اليوم ما محفوظة، بس المجموع.</div>';
}
(function(){
  const _rb=renderBuy; renderBuy=function(){ _rb(); buyDays() };
  const go=dir=>{ const days=[''].concat((settings.daily.history||[]).map(h=>h.date)); const i=days.indexOf(buyView)+dir; if(i>=0&&i<days.length){ buyView=days[i]; renderBuy() } };
  document.getElementById('bdStrip').addEventListener('click',e=>{ const b=e.target.closest('button[data-d]'); if(!b) return; buyView=b.dataset.d; renderBuy() });
  document.getElementById('bdPrev').addEventListener('click',()=>go(1));
  document.getElementById('bdNext').addEventListener('click',()=>go(-1));
})();
