      <div class="bday-nav" role="group" aria-label="اختيار اليوم">
        <button type="button" class="bday-arr" id="bdPrev" aria-label="اليوم الي قبله">›</button>
        <div class="bday-strip" id="bdStrip"></div>
        <button type="button" class="bday-arr" id="bdNext" aria-label="اليوم الي بعده">‹</button>
      </div>
      <h3><span id="buyTitle">مسواك اليوم</span> <span class="note" id="buyDate"></span></h3>
.bday-nav{display:flex;align-items:center;gap:6px;margin-bottom:14px}
.bday-arr{flex:none;width:40px;height:52px;border-radius:12px;border:1px solid var(--line);background:transparent;color:var(--ink);font-size:24px;cursor:pointer}
.bday-arr:disabled{opacity:.3;cursor:default}
.bday-strip{flex:1;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;scroll-snap-type:x proximity}
.bday-strip::-webkit-scrollbar{display:none}
.bday-strip button{flex:none;scroll-snap-align:start;min-width:84px;min-height:52px;padding:4px 10px;border-radius:12px;border:1px solid var(--line);background:transparent;color:var(--ink);font:inherit;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}
.bday-strip button b{font-size:14px}
.bday-strip button small{font-size:12px;color:var(--mut)}
.bday-strip button.on{background:#F5C243;border-color:#F5C243;color:#111}
.bday-strip button.on small{color:#111}
